// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: an arbitrary nonzero length for _tos (we pass a single-entry array),
    // an arbitrary address `from` (fuzzed) and an arbitrary uint v (fuzzed)
    function testFuzz_property(address from, uint256 v) public {
        // keep inputs wide; ensure the _tos array we build is non-empty to be admissible
        address[] memory tos = new address[](1);
        // deploy a helper that reverts on the expected call signature
        Reverter rev = new Reverter();
        tos[0] = address(rev);

        // Call transfer and detect whether it reverted or returned successfully.
        // According to the correct contract C, because the callee reverts, C.transfer MUST revert
        // (the require(_s) enforces propagation). The mutant removing require(_s) will NOT revert
        // and will return true for some inputs. We observe this by trying the call and asserting
        // that it did NOT succeed (i.e. it reverted) for these inputs.

        bool ok;
        try c.transfer(from, address(rev), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible inputs (non-empty tos), the reference C always
        // reverts when the callee reverts; thus ok must be false for all fuzzed inputs here.
        assertTrue(!ok);
    }
}

// Adversarial helper: this contract REVERTS when called with the exact selector
// transferFrom(address,address,uint256) so that the callee call inside C fails.
contract Reverter {
    // Define the exact function so ABI decoding matches; it always reverts.
    function transferFrom(address, address, uint256) external pure {
        revert("revert-from-callee");
    }

    // Also provide a fallback to catch malformed calls (not used here).
    fallback() external payable { revert("fallback"); }
}
